def extract_shapes(grid):
    H,W=len(grid),len(grid[0])
    seen=set(); shapes=[]
    def cells(i,j):
        stack=[(i,j)]; out=[]
        while stack:
            a,b=stack.pop()
            if (a,b) in seen or not(0<=a<H and 0<=b<W) or grid[a][b]==0: continue
            seen.add((a,b)); out.append((a,b))
            stack+= [(a+1,b),(a-1,b),(a,b+1),(a,b-1)]
        return out
    for i in range(H):
        for j in range(W):
            if grid[i][j] and (i,j) not in seen:
                c=cells(i,j)
                if c:
                    rs=[a for a,_ in c]; cs=[b for _,b in c]
                    shapes.append((min(cs),[[grid[a][b] if (a,b) in set(c) else 0 for b in range(min(cs),max(cs)+1)] for a in range(min(rs),max(rs)+1)]))
    shapes.sort()
    return [s for _,s in shapes]

